query ContributionFlowPaymentMethods($slug: String) {
  account(slug: $slug) {
    id
    paymentMethods(
      type: [
        CREDITCARD
        US_BANK_ACCOUNT
        SEPA_DEBIT
        BACS_DEBIT
        GIFTCARD
        PREPAID
        COLLECTIVE
      ]
      includeExpired: true
    ) {
      id
      name
      data
      service
      type
      expiryDate
      providerType
      sourcePaymentMethod {
        id
        name
        data
        service
        type
        expiryDate
        providerType
        balance {
          currency
        }
        limitedToHosts {
          id
          legacyId
          slug
        }
      }
      balance {
        valueInCents
        currency
      }
      account {
        id
        slug
        type
        name
        imageUrl
      }
      limitedToHosts {
        id
        legacyId
        slug
      }
    }
  }
}

query DashboardVendors($slug: String!, $searchTerm: String, $isArchived: Boolean, $limit: Int = 20, $offset: Int = 0, $totalContributed: AmountRangeInput, $totalExpended: AmountRangeInput, $communityTotalContributed: AmountRangeWithYearInput, $communityTotalExpended: AmountRangeWithYearInput, $onlyVendors: Boolean!, $missingInformation: [MissingInformationField!], $orderBy: OrderByInput) {
  account(slug: $slug) {
    id
    legacyId
    publicId
    ... on AccountWithHost {
      host {
        id
        ...HostFields
      }
    }
    ... on Organization {
      host {
        id
        ...HostFields
      }
    }
  }
  community(
    host: { slug: $slug }
    type: [ORGANIZATION]
    searchTerm: $searchTerm
    missingInformation: $missingInformation
    totalContributed: $communityTotalContributed
    totalExpended: $communityTotalExpended
    limit: $limit
    offset: $offset
    orderBy: $orderBy
  ) @skip(if: $onlyVendors) {
    totalCount
    offset
    limit
    nodes {
      id
      publicId
      legacyId
      slug
      name
      legalName
      type
      imageUrl
      communityStats(host: { slug: $slug }) {
        relations
        transactionSummary {
          kind
          debitTotal {
            valueInCents
            currency
          }
          debitCount
          creditTotal {
            valueInCents
            currency
          }
          creditCount
        }
      }
      fiscalHostNote(host: { slug: $slug }) {
        type
        note
        updatedAt
        updatedBy {
          id
          name
          slug
        }
      }
    }
  }
}

fragment AccountHoverCardFields on Account {
  id
  publicId
  name
  legalName
  slug
  type
  description
  imageUrl
  isHost
  isArchived
  isVerified
  hasPublicProfile
  ... on Individual {
    id
    isGuest
  }
  ... on AccountWithHost {
    host {
      id
      slug
      type
      isTrustedHost
      isFirstPartyHost
      isVerified
      hasPublicProfile
    }
    approvedAt
  }
  ... on Organization {
    host {
      id
      slug
      type
      isTrustedHost
      isFirstPartyHost
      isVerified
      hasPublicProfile
    }
  }
  ... on AccountWithParent {
    parent {
      id
      slug
      hasPublicProfile
    }
  }
}

fragment VendorFields on Vendor {
  id
  publicId
  slug
  name
  legalName
  type
  hasPublicProfile
  description
  tags
  imageUrl(height: 96)
  isArchived
  createdAt
  features {
    PUBLIC_PROFILE
  }
  settings
  location {
    id
    address
    country
    name
    structured
  }
  createdByAccount {
    id
    slug
    name
    imageUrl
    ...AccountHoverCardFields
  }
  vendorInfo {
    contact {
      name
      email
    }
    taxFormUrl
    taxFormRequired
    taxType
    taxId
    notes
  }
  payoutMethods {
    id
    type
    name
    data
  }
  orders(filter: OUTGOING, limit: 1) {
    totalCount
  }
  expenses(status: PAID, direction: SUBMITTED, limit: 1) {
    totalCount
  }
  canBeUsedWithAccounts {
    id
    type
    legacyId
    slug
    name
    imageUrl
  }
  useVendorPolicy
}

fragment HostFields on Host {
  id
  legacyId
  name
  legalName
  slug
  type
  expensePolicy
  settings
  currency
  requiredLegalDocuments
  policies {
    id
    USE_VENDOR_POLICY
  }
  features {
    id
    MULTI_CURRENCY_EXPENSES
  }
  location {
    id
    address
    country
  }
  transferwise {
    id
    availableCurrencies
  }
  supportedPayoutMethods
  isTrustedHost
  vendors(
    searchTerm: $searchTerm
    isArchived: $isArchived
    limit: $limit
    offset: $offset
    totalContributed: $totalContributed
    totalExpended: $totalExpended
    orderBy: $orderBy
  ) @include(if: $onlyVendors) {
    totalCount
    offset
    limit
    nodes {
      id
      ...VendorFields
      communityStats(host: { slug: $slug }) {
        relations
        transactionSummary {
          kind
          debitTotal {
            valueInCents
            currency
          }
          debitCount
          creditTotal {
            valueInCents
            currency
          }
          creditCount
        }
      }
      fiscalHostNote(host: { slug: $slug }) {
        type
        note
        updatedAt
        updatedBy {
          id
          name
          slug
        }
      }
    }
  }
}

query HostedCollectives($hostSlug: String!, $includeFiscalHostNote: Boolean! = false, $limit: Int!, $offset: Int!, $sort: OrderByInput, $hostFeesStructure: HostFeeStructure, $searchTerm: String, $type: [AccountType], $isApproved: Boolean, $isFrozen: Boolean, $isUnhosted: Boolean, $balance: AmountRangeInput, $consolidatedBalance: AmountRangeInput, $currencies: [String], $startsAtFrom: DateTime, $startsAtTo: DateTime, $joinedBetween: MetricsDateRangeInput, $unhostedBetween: MetricsDateRangeInput, $hadActivityBetween: MetricsDateRangeInput, $noActivityBetween: MetricsDateRangeInput) {
  host(slug: $hostSlug) {
    id
    legacyId
    slug
    name
    currency
    isHost
    isPrivate
    type
    settings
    hostFeePercent
    ... on AccountWithPlatformSubscription {
      platformSubscription {
        isAccountOnHold
      }
    }
    plan {
      id
      hostFees
      hostFeeSharePercent
    }
    hostedAccounts(
      limit: $limit
      offset: $offset
      searchTerm: $searchTerm
      hostFeesStructure: $hostFeesStructure
      accountType: $type
      orderBy: $sort
      isApproved: $isApproved
      isFrozen: $isFrozen
      isUnhosted: $isUnhosted
      balance: $balance
      consolidatedBalance: $consolidatedBalance
      currencies: $currencies
      startsAtFrom: $startsAtFrom
      startsAtTo: $startsAtTo
      joinedBetween: $joinedBetween
      unhostedBetween: $unhostedBetween
      hadActivityBetween: $hadActivityBetween
      noActivityBetween: $noActivityBetween
    ) {
      offset
      limit
      totalCount
      nodes {
        id
        unhostedAt(host: { slug: $hostSlug })
        fiscalHostNote(host: { slug: $hostSlug }) @include(if: $includeFiscalHostNote) {
          type
          note
          updatedAt
          updatedBy {
            id
            name
            slug
          }
        }
        ...HostedCollectiveFields
      }
    }
  }
}

