query PeopleHostDashboard($slug: String!, $offset: Int, $limit: Int, $relation: [CommunityRelationType!], $missingInformation: [MissingInformationField!], $searchTerm: String, $account: AccountReferenceInput, $totalContributed: AmountRangeWithYearInput, $totalExpended: AmountRangeWithYearInput, $orderBy: OrderByInput) {
  community(
    host: { slug: $slug }
    relation: $relation
    missingInformation: $missingInformation
    account: $account
    type: [INDIVIDUAL]
    searchTerm: $searchTerm
    totalContributed: $totalContributed
    totalExpended: $totalExpended
    offset: $offset
    limit: $limit
    orderBy: $orderBy
  ) {
    limit
    offset
    nodes {
      id
      legacyId
      publicId
      slug
      name
      legalName
      type
      imageUrl
      isIncognito
      ... on Individual {
        isGuest
        email
        location {
          country
        }
        kycStatus(requestedByAccount: { slug: $slug }) {
          ...KYCStatusFields
        }
      }
      communityStats(host: { slug: $slug }) {
        relations
        transactionSummary {
          kind
          debitTotal {
            valueInCents
            currency
          }
          debitCount
          creditTotal {
            valueInCents
            currency
          }
          creditCount
        }
      }
      fiscalHostNote(host: { slug: $slug }) {
        type
        note
        updatedAt
        updatedBy {
          id
          name
          slug
        }
      }
    }
  }
}

