query CommunityAccountDetail($accountId: String!, $hostSlug: String!, $includeFiscalHostNote: Boolean! = false) {
  account(id: $accountId) {
    id
    publicId
    legacyId
    slug
    name
    legalName
    taxableCountry
    isUSEntity
    type
    createdAt
    hasPublicProfile
    ... on Organization {
      canBeVendorOf(host: { slug: $hostSlug })
    }
    socialLinks {
      type
      url
    }
    location {
      id
      country
      address
    }
    isArchived
    spamExpenses: expenses(
      status: [SPAM]
      direction: SUBMITTED
      host: { slug: $hostSlug }
    ) {
      totalCount
    }
    rejectedExpenses: expenses(
      status: [REJECTED]
      direction: SUBMITTED
      host: { slug: $hostSlug }
    ) {
      totalCount
    }
    communityStats(host: { slug: $hostSlug }) {
      id
      relations
    }
    fiscalHostNote(host: { slug: $hostSlug }) {
      type
      note
      updatedAt
      updatedBy {
        id
        name
        slug
      }
    }
    ... on Individual {
      email
      kycStatus(requestedByAccount: { slug: $hostSlug }) {
        manual {
          ...KYCVerificationFields
        }
      }
      adminOf: memberOf(
        role: [ADMIN]
        accountType: [ORGANIZATION, VENDOR, COLLECTIVE, FUND]
      ) {
        nodes {
          id
          account {
            ...AccountHoverCardFields
          }
        }
      }
    }
    ... on Vendor {
      ...VendorFields
    }
    description
    longDescription
    updates(includeChildren: true, onlyPublishedUpdates: true, limit: 0) {
      totalCount
    }
    firstTransaction: transactions(
      limit: 1
      offset: 0
      orderBy: { field: CREATED_AT, direction: ASC }
      includeChildrenTransactions: true
      host: { slug: $hostSlug }
    ) {
      nodes {
        id
        ...CommunityAccountDetailTransaction
      }
    }
    recentContributions: transactions(
      limit: 5
      offset: 0
      kind: [CONTRIBUTION, ADDED_FUNDS]
      includeChildrenTransactions: true
      host: { slug: $hostSlug }
    ) {
      nodes {
        id
        ...CommunityAccountDetailTransaction
      }
    }
    recentPayouts: transactions(
      limit: 5
      offset: 0
      kind: [EXPENSE]
      includeChildrenTransactions: true
      host: { slug: $hostSlug }
    ) {
      nodes {
        id
        ...CommunityAccountDetailTransaction
      }
    }
    childrenAccounts {
      nodes {
        id
        ... on AccountWithHost {
          host {
            id
            legacyId
            name
            slug
            imageUrl
          }
        }
      }
    }
    ...HostedCollectiveFields
  }
  host(slug: $hostSlug) {
    id
    legacyId
    slug
    name
    hostedLegalDocuments(
      type: US_TAX_FORM
      account: { id: $accountId }
      limit: 1
      orderBy: { field: CREATED_AT, direction: DESC }
    ) {
      totalCount
      nodes {
        ...LegalDocumentFields
      }
    }
    features {
      id
      MULTI_CURRENCY_EXPENSES
    }
    requiredLegalDocuments
    currency
    transferwise {
      id
      availableCurrencies
    }
    supportedPayoutMethods
    isTrustedHost
    policies {
      id
      USE_VENDOR_POLICY
    }
    hostFeePercent
    hostedAccountAgreements(
      accounts: [{ id: $accountId }]
      includeChildren: true
      limit: 0
    ) {
      totalCount
    }
  }
}

