query AccountExpenses($account: AccountReferenceInput, $fromAccount: AccountReferenceInput, $fromAccounts: [AccountReferenceInput], $limit: Int!, $offset: Int!, $type: ExpenseType, $types: [ExpenseType], $tags: [String], $status: [ExpenseStatusFilter], $amount: AmountRangeInput, $payoutMethod: PayoutMethodReferenceInput, $payoutMethodType: PayoutMethodType, $dateFrom: DateTime, $dateTo: DateTime, $searchTerm: String, $sort: ChronologicalOrderInput, $chargeHasReceipts: Boolean, $virtualCards: [VirtualCardReferenceInput], $createdByAccount: AccountReferenceInput, $approvedByAccount: AccountReferenceInput, $paidByAccount: AccountReferenceInput, $rejectedByAccount: AccountReferenceInput, $includeChildrenExpenses: Boolean, $fetchHostForExpenses: Boolean!, $hasAmountInCreatedByAccountCurrency: Boolean!, $accountingCategory: [String], $fetchGrantHistory: Boolean!, $hostSlug: String, $includeFiscalHostNote: Boolean! = false) {
  expenses(
    account: $account
    fromAccount: $fromAccount
    fromAccounts: $fromAccounts
    limit: $limit
    offset: $offset
    type: $type
    types: $types
    tag: $tags
    status: $status
    amount: $amount
    payoutMethod: $payoutMethod
    payoutMethodType: $payoutMethodType
    dateFrom: $dateFrom
    dateTo: $dateTo
    searchTerm: $searchTerm
    orderBy: $sort
    chargeHasReceipts: $chargeHasReceipts
    virtualCards: $virtualCards
    createdByAccount: $createdByAccount
    includeChildrenExpenses: $includeChildrenExpenses
    accountingCategory: $accountingCategory
    paidByAccount: $paidByAccount
    approvedByAccount: $approvedByAccount
    rejectedByAccount: $rejectedByAccount
  ) {
    totalCount
    offset
    limit
    nodes {
      id
      ...ExpensesListFields
      account {
        fiscalHostNote(host: { slug: $hostSlug }) @include(if: $includeFiscalHostNote) {
          type
          note
          updatedAt
          updatedBy {
            id
            name
            slug
          }
        }
      }
      createdByAccount {
        fiscalHostNote(host: { slug: $hostSlug }) @include(if: $includeFiscalHostNote) {
          type
          note
          updatedAt
          updatedBy {
            id
            name
            slug
          }
        }
      }
      amountInCreatedByAccountCurrency: amountV2(currencySource: CREATED_BY_ACCOUNT) @include(if: $hasAmountInCreatedByAccountCurrency) {
        value
        valueInCents
        currency
        exchangeRate {
          date
          value
          source
          isApproximate
          fromCurrency
          toCurrency
        }
      }
      host @include(if: $fetchHostForExpenses) {
        id
        ...ExpenseHostFields
      }
      payee {
        fiscalHostNote(host: { slug: $hostSlug }) @include(if: $includeFiscalHostNote) {
          type
          note
          updatedAt
          updatedBy {
            id
            name
            slug
          }
        }
        grantHistory: expenses(
          status: PAID
          type: GRANT
          direction: SUBMITTED
          limit: 1
          account: $account
        ) @include(if: $fetchGrantHistory) {
          totalAmount {
            amount {
              currency
              valueInCents
            }
          }
          totalCount
        }
      }
    }
  }
}

