query OverviewMetrics($slug: String!, $dateFrom: DateTime, $dateTo: DateTime, $compareFrom: DateTime, $compareTo: DateTime, $includeComparison: Boolean!, $includeChildren: Boolean, $includeBalance: Boolean!, $includeBalanceTimeseries: Boolean!, $includeSpent: Boolean!, $includeReceived: Boolean!, $includeReceivedTimeseries: Boolean!, $includeContributionsCount: Boolean!, $timeUnit: TimeUnit) {
  account(slug: $slug) {
    id
    isActive
    ...AccountHoverCardFields
    balance: stats @include(if: $includeBalance) {
      id
      current: balance(includeChildren: $includeChildren, dateTo: $dateTo) {
        currency
        valueInCents
      }
      comparison: balance(includeChildren: $includeChildren, dateTo: $compareTo) @include(if: $includeComparison) {
        currency
        valueInCents
      }
    }
    balanceTimeseries: stats @include(if: $includeBalanceTimeseries) {
      id
      current: balanceTimeSeries(
        includeChildren: $includeChildren
        dateFrom: $dateFrom
        dateTo: $dateTo
        timeUnit: $timeUnit
      ) {
        dateTo
        dateFrom
        timeUnit
        nodes {
          date
          amount {
            currency
            value
          }
        }
      }
      comparison: balanceTimeSeries(
        includeChildren: $includeChildren
        dateFrom: $compareFrom
        dateTo: $compareTo
        timeUnit: $timeUnit
      ) @include(if: $includeComparison) {
        dateTo
        dateFrom
        timeUnit
        nodes {
          date
          amount {
            currency
            value
          }
        }
      }
    }
    spent: stats @include(if: $includeSpent) {
      id
      current: totalAmountSpent(
        includeChildren: $includeChildren
        dateFrom: $dateFrom
        dateTo: $dateTo
        net: true
      ) {
        currency
        valueInCents
      }
      comparison: totalAmountSpent(
        includeChildren: $includeChildren
        dateFrom: $compareFrom
        dateTo: $compareTo
        net: true
      ) @include(if: $includeComparison) {
        currency
        valueInCents
      }
    }
    received: stats @include(if: $includeReceived) {
      id
      current: totalAmountReceived(
        includeChildren: $includeChildren
        dateFrom: $dateFrom
        dateTo: $dateTo
        net: true
      ) @include(if: $includeReceived) {
        currency
        valueInCents
      }
      comparison: totalAmountReceived(
        includeChildren: $includeChildren
        dateFrom: $compareFrom
        dateTo: $compareTo
        net: true
      ) @include(if: $includeComparison) {
        currency
        valueInCents
      }
    }
    receivedTimeseries: stats @include(if: $includeReceivedTimeseries) {
      id
      current: totalAmountReceivedTimeSeries(
        includeChildren: $includeChildren
        dateFrom: $dateFrom
        dateTo: $dateTo
        timeUnit: $timeUnit
        net: true
      ) {
        dateTo
        dateFrom
        timeUnit
        nodes {
          date
          amount {
            currency
            value
          }
        }
      }
      comparison: totalAmountReceivedTimeSeries(
        includeChildren: $includeChildren
        dateFrom: $compareFrom
        dateTo: $compareTo
        timeUnit: $timeUnit
        net: true
      ) @include(if: $includeComparison) {
        dateTo
        dateFrom
        timeUnit
        nodes {
          date
          amount {
            currency
            value
          }
        }
      }
    }
    contributionsCount: stats @include(if: $includeContributionsCount) {
      id
      current: contributionsCount(
        includeChildren: $includeChildren
        dateFrom: $dateFrom
        dateTo: $dateTo
      )
      comparison: contributionsCount(
        includeChildren: $includeChildren
        dateFrom: $compareFrom
        dateTo: $compareTo
      ) @include(if: $includeComparison)
    }
  }
}

