query OffPlatformTransactions($hostSlug: String, $limit: Int = 50, $offset: Int = 0, $status: TransactionsImportRowStatus, $searchTerm: String, $subAccountId: [NonEmptyString], $importIds: [NonEmptyString!], $importId: NonEmptyString!, $hasImportFilter: Boolean!, $fetchOnlyRowIds: Boolean!, $orderBy: TransactionsImportRowOrderInput) {
  host(slug: $hostSlug) {
    id
    name
    legalName
    imageUrl
    legacyId
    slug
    currency
    type
    policies {
      id
      publicId
      REQUIRE_2FA_FOR_ADMINS
    }
    accountingCategories @skip(if: $fetchOnlyRowIds) {
      totalCount
      nodes {
        id
        ...AccountingCategorySelectFields
      }
    }
    transactionsImports(status: ACTIVE, type: [PLAID, GOCARDLESS], limit: 100) @skip(if: $fetchOnlyRowIds) {
      totalCount
      nodes {
        id
        publicId
        source
        name
      }
    }
    offPlatformTransactionsStats @skip(if: $fetchOnlyRowIds) {
      ...TransactionsImportStats
    }
    offPlatformTransactions(
      limit: $limit
      offset: $offset
      status: $status
      searchTerm: $searchTerm
      accountId: $subAccountId
      importType: [PLAID, GOCARDLESS]
      importId: $importIds
      orderBy: $orderBy
    ) {
      totalCount
      offset
      limit
      nodes {
        id
        ...TransactionsImportRowFields @skip(if: $fetchOnlyRowIds)
        transactionsImport @skip(if: $fetchOnlyRowIds) {
          id
          publicId
          source
          name
        }
        institutionAccount @skip(if: $fetchOnlyRowIds) {
          id
          name
        }
      }
    }
  }
  transactionsImport(id: $importId) @include(if: $hasImportFilter) {
    id
    lastSyncAt
    connectedAccount {
      id
    }
    institutionAccounts {
      id
      name
      type
      subtype
