query KYCTabPeopleDashboard($verifyAccountId: String!, $requestedByAccount: AccountReferenceInput!, $limit: Int!, $offset: Int!) {
  verifyAccount: account(id: $verifyAccountId) {
    id
    ... on Individual {
      kycVerifications(
        requestedByAccounts: [$requestedByAccount]
        limit: $limit
        offset: $offset
      ) {
        ...KYCVerificationCollectionFields
        nodes {
          ... on KYCVerification {
            account {
              ...AccountHoverCardFields
            }
          }
        }
      }
    }
  }
}

