query SearchCommand($searchTerm: String!, $host: AccountReferenceInput, $account: AccountReferenceInput, $limit: Int!, $imageHeight: Int, $useTopHits: Boolean, $includeAccounts: Boolean!, $includeComments: Boolean!, $includeExpenses: Boolean!, $includeTransactions: Boolean!, $includeOrders: Boolean!, $includeUpdates: Boolean!, $includeHostApplications: Boolean!, $offset: Int) {
  search(
    searchTerm: $searchTerm
    defaultLimit: $limit
    host: $host
    account: $account
    useTopHits: $useTopHits
  ) {
    results {
      accounts(limit: $limit, offset: $offset) @include(if: $includeAccounts) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchAccountFields
          }
        }
      }
      comments(limit: $limit, offset: $offset) @include(if: $includeComments) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchCommentFields
          }
        }
      }
      expenses(limit: $limit, offset: $offset) @include(if: $includeExpenses) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          offset
          nodes {
            ...SearchExpenseFields
          }
        }
      }
      orders(limit: $limit, offset: $offset) @include(if: $includeOrders) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchOrderFields
          }
        }
      }
      transactions(limit: $limit, offset: $offset) @include(if: $includeTransactions) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchTransactionFields
          }
        }
      }
      updates(limit: $limit, offset: $offset) @include(if: $includeUpdates) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchUpdateFields
          }
        }
      }
      hostApplications(limit: $limit, offset: $offset) @include(if: $includeHostApplications) {
        highlights
        totalCountIsCapped
        maxScore
        scores {
          id
          score
        }
        collection {
          totalCount
          limit
          nodes {
            ...SearchHostApplicationFields
          }
        }
      }
    }
  }
}

