query ExpenseFormSchema($collectiveSlug: String, $hasCollectiveSlug: Boolean!, $payeeSlug: String, $hasPayeeSlug: Boolean!, $submitterSlug: String, $hasSubmitterSlug: Boolean!, $hasExpenseId: Boolean!, $expenseId: Int, $expenseKey: String) {
  account(slug: $collectiveSlug) @include(if: $hasCollectiveSlug) {
    ...ExpenseFormAccountFields
    ... on AccountWithHost {
      host {
        vendorsForAccount: vendors(
          canBeUsedWithAccounts: [{ slug: $collectiveSlug }]
          limit: 5
        ) {
          nodes {
            ...ExpenseVendorFields
          }
        }
        vendors(canBeUsedWithAccounts: [{ slug: $collectiveSlug }], limit: 1) {
          totalCount
        }
      }
    }
    ... on Organization {
      host {
        vendorsForAccount: vendors(
          canBeUsedWithAccounts: [{ slug: $collectiveSlug }]
          limit: 5
        ) {
          nodes {
            ...ExpenseVendorFields
          }
        }
        vendors(canBeUsedWithAccounts: [{ slug: $collectiveSlug }], limit: 1) {
          totalCount
        }
      }
    }
  }
  payee: account(slug: $payeeSlug) @include(if: $hasPayeeSlug) {
    ...ExpenseFormPayeeFields
    ... on Vendor {
      hasPayoutMethod
    }
  }
  loggedInAccount {
    id
    legacyId
    ...LoggedInAccountExpensePayoutFields
  }
  submitter: account(slug: $submitterSlug) @include(if: $hasSubmitterSlug) {
    ...ExpenseFormSubmitterFields
  }
  recentlySubmittedExpenses: expenses(
    createdByAccount: { slug: $submitterSlug }
    limit: 10
    types: [INVOICE, RECEIPT]
    orderBy: { field: CREATED_AT, direction: DESC }
  ) @include(if: $hasSubmitterSlug) {
    nodes {
      account {
        ...ExpenseFormAccountFields
      }
      payee {
        ...ExpenseFormAccountFields
      }
      payoutMethod {
        id
      }
    }
  }
  expense(expense: { legacyId: $expenseId }, draftKey: $expenseKey) @include(if: $hasExpenseId) {
    id
    legacyId
    description
    createdAt
    longDescription
    amountV2 {
      valueInCents
      currency
    }
    taxes {
      id
      type
      rate
      idNumber
    }
    requiredLegalDocuments
    accountingCategory {
      id
    }
    currency
    type
    status
    account {
      ...ExpenseFormAccountFields
    }
    createdByAccount {
      ...ExpenseFormAccountFields
    }
    payee {
      ...ExpenseFormPayeeFields
    }
    payoutMethod {
      id
      data
    }
    attachedFiles {
      id
      url
      info {
        name
        type
        size
      }
    }
    invoiceFile {
      id
      url
      name
      type
      size
      ... on ImageFileInfo {
        width
      }
    }
    items {
      id
      description
      url
      file {
        name
        type
        size
      }
      amount: amountV2 {
        currency
        valueInCents
        exchangeRate {
          value
          source
          fromCurrency
          toCurrency
          date
        }
      }
      createdAt
      incurredAt
    }
    privateMessage
    invoiceInfo
    reference
    tags
    permissions {
      id
      canEdit
      canEditAccountingCategory
      canEditTags
      canDeclineExpenseInvite(draftKey: $expenseKey)
    }
    draft
    lockedFields
    submitter: createdByAccount {
      ...ExpenseFormSubmitterFields
    }
  }
}

